import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import { viteSingleFile } from 'vite-plugin-singlefile';

export default defineConfig({
  plugins: [react(), viteSingleFile()],
  build: { assetsInlineLimit: Number.POSITIVE_INFINITY },
});

import { parseBoardCode, type Board } from './board.ts';

export const MISMATCH_MS = 800;
export const MAX_MOVES = 999_999;
export const MAX_ELAPSED_MS = 359_999_999;

export interface ClosedSelection {
  readonly kind: 'closed';
}
export interface OneSelection {
  readonly kind: 'one';
  readonly index: number;
}
export interface MismatchSelection {
  readonly kind: 'mismatch';
  readonly first: number;
  readonly second: number;
  readonly remainingMs: number;
}
export type Selection = ClosedSelection | OneSelection | MismatchSelection;

export interface GameState {
  readonly board: Board;
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

const CLOSED: ClosedSelection = Object.freeze({ kind: 'closed' });

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  return board === null ? null : initialGame(board);
}

export function initialGame(board: Board): GameState {
  return { board, matched: Object.freeze([]), selection: CLOSED, moves: 0, elapsedMs: 0, started: false };
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.board.deck.length) return state;
  if (state.selection.kind === 'mismatch' || state.matched.includes(index)) return state;

  if (state.selection.kind === 'closed') {
    return { ...state, selection: { kind: 'one', index }, started: true };
  }
  if (state.selection.index === index) return state;

  const moves = Math.min(MAX_MOVES, state.moves + 1);
  const firstFace = state.board.deck[state.selection.index];
  const secondFace = state.board.deck[index];
  if (firstFace === undefined || secondFace === undefined) return state;
  if (firstFace !== secondFace) {
    return {
      ...state,
      moves,
      selection: { kind: 'mismatch', first: state.selection.index, second: index, remainingMs: MISMATCH_MS },
    };
  }

  return {
    ...state,
    moves,
    matched: Object.freeze([...state.matched, state.selection.index, index]),
    selection: CLOSED,
  };
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isSafeInteger(milliseconds) || milliseconds < 0 || !state.started || isWon(state)) return state;
  if (state.selection.kind !== 'mismatch') {
    return milliseconds === 0 ? state : { ...state, elapsedMs: addElapsed(state.elapsedMs, milliseconds) };
  }

  const used = Math.min(milliseconds, state.selection.remainingMs);
  const elapsedMs = addElapsed(state.elapsedMs, used);
  const remaining = state.selection.remainingMs - used;
  if (remaining > 0) {
    return { ...state, elapsedMs, selection: { ...state.selection, remainingMs: remaining } };
  }

  const afterClose = { ...state, elapsedMs, selection: CLOSED };
  const extra = milliseconds - used;
  return extra === 0 ? afterClose : { ...afterClose, elapsedMs: addElapsed(elapsedMs, extra) };
}

function addElapsed(current: number, amount: number): number {
  return amount >= MAX_ELAPSED_MS - current ? MAX_ELAPSED_MS : current + amount;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

export function matchedPairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function totalPairCount(state: GameState): number {
  return state.board.deck.length / 2;
}

export function formatElapsedTime(milliseconds: number): string {
  const seconds = Math.floor(milliseconds / 1000);
  const minutes = Math.floor(seconds / 60);
  return `${minutes}:${String(seconds % 60).padStart(2, '0')}`;
}
export const GRID_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type GridSize = (typeof GRID_SIZES)[number];

export interface Board {
  readonly boardCode: string;
  readonly size: GridSize;
  readonly seed: number;
  readonly deck: readonly number[];
}

export const isGridSize = (value: unknown): value is GridSize =>
  typeof value === 'number' && GRID_SIZES.some((size) => size === value);

const MAX_SEED = 2_147_483_646;
const PARK_MILLER_MODULUS = 2_147_483_647;
const PARK_MILLER_MULTIPLIER = 16_807;
const RANDOM_VALUES = PARK_MILLER_MODULUS - 1;

export function parseBoardCode(boardCode: string): Board | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(boardCode);
  const sizeText = match?.[1];
  const seedText = match?.[2];
  if (sizeText === undefined || seedText === undefined) return null;

  const size = Number(sizeText);
  const seed = Number(seedText);
  if (!isGridSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;

  const deck = generateDeck(size, seed);
  return Object.freeze({ boardCode, size, seed, deck });
}

function generateDeck(size: GridSize, seed: number): readonly number[] {
  const cards = Array.from({ length: size * size }, (_, index) => Math.floor(index / 2));
  let state = seed;

  for (let index = cards.length - 1; index > 0; index -= 1) {
    const bound = index + 1;
    const limit = Math.floor(RANDOM_VALUES / bound) * bound;
    let draw: number;
    do {
      state = (state * PARK_MILLER_MULTIPLIER) % PARK_MILLER_MODULUS;
      draw = state - 1;
    } while (draw >= limit);

    const other = draw % bound;
    const currentCard = cards[index];
    const otherCard = cards[other];
    if (currentCard === undefined || otherCard === undefined) {
      throw new Error('Shuffle index outside the deck.');
    }
    cards[index] = otherCard;
    cards[other] = currentCard;
  }

  return Object.freeze(cards);
}

import { parseBoardCode } from './board.ts';
import type { GameState, Selection } from './state.ts';
import { initialGame } from './state.ts';

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_BYTE_LIMIT = 65_536;

type SnapshotObject = {
  readonly version: 1;
  readonly boardCode: string;
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
};

export function encodeSnapshot(state: GameState): string {
  const value: SnapshotObject = {
    version: SNAPSHOT_VERSION,
    boardCode: state.board.boardCode,
    matched: state.matched,
    selection: state.selection,
    moves: state.moves,
    elapsedMs: state.elapsedMs,
    started: state.started,
  };
  return JSON.stringify(value);
}

export function decodeSnapshot(text: string): GameState | null {
  if (new TextEncoder().encode(text).length > SNAPSHOT_BYTE_LIMIT) return null;
  let value: unknown;
  try {
    value = JSON.parse(text);
  } catch {
    return null;
  }
  return readSnapshot(value);
}

function readSnapshot(value: unknown): GameState | null {
  if (!hasKeys(value, ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'])) {
    return null;
  }
  if (value.version !== SNAPSHOT_VERSION || typeof value.boardCode !== 'string') return null;
  if (!isUnknownArray(value.matched) || !isSafeCount(value.moves, 999_999)) return null;
  if (!isSafeCount(value.elapsedMs, 359_999_999) || typeof value.started !== 'boolean') return null;

  const board = parseBoardCode(value.boardCode);
  if (board === null) return null;
  const matched = readMatched(value.matched, board.deck);
  const selection = readSelection(value.selection, board.deck, matched);
  if (matched === null || selection === null) return null;

  const pairCount = matched.length / 2;
  const minimumMoves = pairCount + (selection.kind === 'mismatch' ? 1 : 0);
  if (value.moves < minimumMoves) return null;
  const complete = matched.length === board.deck.length;
  if (complete && selection.kind !== 'closed') return null;
  if (!value.started) {
    if (value.moves !== 0 || value.elapsedMs !== 0 || matched.length !== 0 || selection.kind !== 'closed') {
      return null;
    }
  } else if (value.moves === 0 && selection.kind !== 'one') {
    return null;
  }

  const game = initialGame(board);
  return { ...game, matched: Object.freeze(matched), selection, moves: value.moves, elapsedMs: value.elapsedMs, started: value.started };
}

function readMatched(value: readonly unknown[], deck: readonly number[]): number[] | null {
  const matched: number[] = [];
  for (const index of value) {
    if (!isIndex(index, deck.length) || matched.includes(index)) return null;
    matched.push(index);
  }
  const matchedSet = new Set(matched);
  for (const index of matched) {
    const face = deck[index];
    if (face === undefined) return null;
    const partner = deck.findIndex((candidate, position) => candidate === face && position !== index);
    if (partner < 0 || !matchedSet.has(partner)) return null;
  }
  return matched;
}

function readSelection(value: unknown, deck: readonly number[], matched: readonly number[]): Selection | null {
  if (!isRecord(value) || typeof value.kind !== 'string') return null;
  if (value.kind === 'closed') return hasKeys(value, ['kind']) ? { kind: 'closed' } : null;
  if (value.kind === 'one') {
    if (!hasKeys(value, ['kind', 'index']) || !isIndex(value.index, deck.length) || matched.includes(value.index)) return null;
    return { kind: 'one', index: value.index };
  }
  if (value.kind === 'mismatch') {
    if (!hasKeys(value, ['kind', 'first', 'second', 'remainingMs'])) return null;
    if (!isIndex(value.first, deck.length) || !isIndex(value.second, deck.length)) return null;
    if (value.first === value.second || matched.includes(value.first) || matched.includes(value.second)) return null;
    if (deck[value.first] === deck[value.second] || !isSafeCount(value.remainingMs, 800) || value.remainingMs === 0) {
      return null;
    }
    return { kind: 'mismatch', first: value.first, second: value.second, remainingMs: value.remainingMs };
  }
  return null;
}

function isIndex(value: unknown, length: number): value is number {
  return Number.isSafeInteger(value) && typeof value === 'number' && value >= 0 && value < length;
}

function isSafeCount(value: unknown, maximum: number): value is number {
  return Number.isSafeInteger(value) && typeof value === 'number' && value >= 0 && value <= maximum;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isUnknownArray(value: unknown): value is readonly unknown[] {
  return Array.isArray(value);
}

function hasKeys(value: unknown, keys: readonly string[]): value is Record<string, unknown> {
  if (!isRecord(value)) return false;
  const ownKeys = Object.keys(value);
  return ownKeys.length === keys.length && keys.every((key) => Object.hasOwn(value, key));
}

import { parseBoardCode } from './board.ts';
import { advanceGame, activateCard, initialGame, type GameState } from './state.ts';

export const REPLAY_VERSION = 1;
export const REPLAY_BYTE_LIMIT = 1_048_576;
export const REPLAY_ACTION_LIMIT = 10_000;

interface ReplayAction {
  readonly atMs: number;
  readonly index: number;
}

interface ReplayInput {
  readonly boardCode: string;
  readonly actions: readonly ReplayAction[];
  readonly endMs: number;
}

export function replayGame(text: string): GameState | null {
  if (new TextEncoder().encode(text).length > REPLAY_BYTE_LIMIT) return null;
  let value: unknown;
  try {
    value = JSON.parse(text);
  } catch {
    return null;
  }
  const replay = readReplay(value);
  if (replay === null) return null;

  const board = parseBoardCode(replay.boardCode);
  if (board === null) return null;
  let state = initialGame(board);
  let currentMs = 0;
  for (const action of replay.actions) {
    state = advanceGame(state, action.atMs - currentMs);
    state = activateCard(state, action.index);
    currentMs = action.atMs;
  }
  return advanceGame(state, replay.endMs - currentMs);
}

function readReplay(value: unknown): ReplayInput | null {
  if (!hasKeys(value, ['version', 'boardCode', 'actions', 'endMs'])) return null;
  if (value.version !== REPLAY_VERSION || typeof value.boardCode !== 'string') return null;
  if (!isUnknownArray(value.actions) || value.actions.length > REPLAY_ACTION_LIMIT) return null;
  if (!isTime(value.endMs)) return null;

  const board = parseBoardCode(value.boardCode);
  if (board === null) return null;
  const actions: ReplayAction[] = [];
  let previousTime = 0;
  for (const item of value.actions) {
    if (!hasKeys(item, ['atMs', 'index']) || !isTime(item.atMs)) return null;
    if (!isIndex(item.index, board.deck.length) || item.atMs < previousTime) return null;
    actions.push({ atMs: item.atMs, index: item.index });
    previousTime = item.atMs;
  }
  if (previousTime > value.endMs) return null;
  return { boardCode: value.boardCode, actions, endMs: value.endMs };
}

function isTime(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

function isIndex(value: unknown, length: number): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 && value < length;
}

function isUnknownArray(value: unknown): value is readonly unknown[] {
  return Array.isArray(value);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function hasKeys(value: unknown, keys: readonly string[]): value is Record<string, unknown> {
  if (!isRecord(value)) return false;
  const ownKeys = Object.keys(value);
  return ownKeys.length === keys.length && keys.every((key) => Object.hasOwn(value, key));
}
import { readFileSync } from 'node:fs';
import { encodeSnapshot } from '../src/game/snapshot.ts';
import { replayGame } from '../src/game/replay.ts';

const path = process.argv[2];
if (path === undefined) {
  process.stderr.write('Invalid replay.\n');
  process.exitCode = 1;
} else {
  try {
    const text = readFileSync(path, 'utf8');
    const state = replayGame(text);
    if (state === null) throw new Error('Invalid replay.');
    process.stdout.write(`${encodeSnapshot(state)}\n`);
  } catch {
    process.stderr.write('Invalid replay.\n');
    process.exitCode = 1;
  }
}

import { describe, expect, it } from 'vitest';
import { GRID_SIZES, isGridSize, parseBoardCode } from './board.ts';

describe('board codes', () => {
  it('repeats the documented version 1 deal', () => {
    const board = parseBoardCode('np1-4-1');
    expect(board?.deck).toEqual([6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3]);
    expect(Object.isFrozen(board?.deck)).toBe(true);
    expect(Object.isFrozen(board)).toBe(true);
  });

  it('creates pairs for every supported grid size', () => {
    for (const size of GRID_SIZES) {
      const board = parseBoardCode(`np1-${size}-2147483646`);
      expect(board?.deck).toHaveLength(size * size);
      const counts = new Map<number, number>();
      for (const face of board?.deck ?? []) counts.set(face, (counts.get(face) ?? 0) + 1);
      expect([...counts.values()].every((count) => count === 2)).toBe(true);
    }
  });

  it('accepts only the exact code form and supported sizes', () => {
    for (const code of [
      'np1-4-0', 'np1-4-01', 'np1-5-1', 'np1-4-2147483647', 'np1-4-9007199254740992',
      ' np1-4-1', 'np1-4-1 ', 'np1-4-1\n', 'np1-4-1\r\n', 'NP1-4-1',
    ]) expect(parseBoardCode(code)).toBeNull();
    expect(isGridSize(4)).toBe(true);
    expect(isGridSize(5)).toBe(false);
  });
});
import { describe, expect, it } from 'vitest';
import { createGame, activateCard, advanceGame, formatElapsedTime, isWon, MAX_ELAPSED_MS, MAX_MOVES } from './state.ts';

describe('game turns and logical time', () => {
  it('starts on a valid reveal and ignores repeats and matched cards', () => {
    const start = createGame('np1-4-1');
    if (start === null) throw new Error('Expected a valid board.');
    const first = activateCard(start, 0);
    expect(first.started).toBe(true);
    expect(first.moves).toBe(0);
    expect(activateCard(first, 0)).toBe(first);
    const match = activateCard(first, 11);
    expect(match.moves).toBe(1);
    expect(match.matched).toEqual([0, 6]);
    expect(activateCard(match, 0)).toBe(match);
  });

  it('holds a mismatch for exactly 800 active milliseconds and ignores input', () => {
    const start = createGame('np1-4-1');
    if (start === null) throw new Error('Expected a valid board.');
    const first = activateCard(activateCard(start, 0), 1);
    expect(first.selection).toEqual({ kind: 'mismatch', first: 0, second: 1, remainingMs: 800 });
    expect(first.moves).toBe(1);
    expect(activateCard(first, 2)).toBe(first);
    const beforeClose = advanceGame(first, 799);
    expect(beforeClose.selection).toEqual({ kind: 'mismatch', first: 0, second: 1, remainingMs: 1 });
    expect(beforeClose.elapsedMs).toBe(799);
    const closed = advanceGame(beforeClose, 1);
    expect(closed.selection).toEqual({ kind: 'closed' });
    expect(closed.elapsedMs).toBe(800);
  });

  it('caps moves and elapsed time without stopping turns or mismatch closing', () => {
    const start = createGame('np1-4-1');
    if (start === null) throw new Error('Expected a valid board.');
    const cappedMoves = { ...start, moves: MAX_MOVES };
    const miss = activateCard(activateCard(cappedMoves, 0), 1);
    expect(miss.moves).toBe(MAX_MOVES);
    const cappedTime = advanceGame(activateCard(start, 0), Number.MAX_SAFE_INTEGER);
    expect(cappedTime.elapsedMs).toBe(MAX_ELAPSED_MS);
    const cappedMismatch = { ...miss, elapsedMs: MAX_ELAPSED_MS };
    expect(advanceGame(cappedMismatch, 800).selection.kind).toBe('closed');
  });

  it('derives victory and formats minutes beyond an hour', () => {
    const start = createGame('np1-4-1');
    if (start === null) throw new Error('Expected a valid board.');
    let finished = start;
    for (let position = 0; position < start.board.deck.length; position += 1) {
      if (finished.matched.includes(position)) continue;
      const mate = start.board.deck.findIndex((face, index) => index !== position && face === start.board.deck[position]);
      finished = activateCard(activateCard(finished, position), mate);
    }
    expect(isWon(finished)).toBe(true);
    expect(formatElapsedTime(3_600_000)).toBe('60:00');
    expect(formatElapsedTime(359_999_999)).toBe('5999:59');
  });
});
import { describe, expect, it } from 'vitest';
import { createGame, activateCard } from './state.ts';
import { decodeSnapshot, encodeSnapshot } from './snapshot.ts';

const mismatchJson = '{"version":1,"boardCode":"np1-4-1","matched":[0,11],"selection":{"kind":"mismatch","first":1,"second":2,"remainingMs":300},"moves":2,"elapsedMs":1500,"started":true}';

describe('snapshot format', () => {
  it('loads the documented snapshot and preserves its version 1 JSON shape', () => {
    const state = decodeSnapshot(mismatchJson);
    expect(state?.selection).toEqual({ kind: 'mismatch', first: 1, second: 2, remainingMs: 300 });
    expect(state?.matched).toEqual([0, 11]);
    expect(state === null ? null : JSON.parse(encodeSnapshot(state))).toEqual(JSON.parse(mismatchJson));
  });

  it('round trips an initial and a live mismatch state', () => {
    const start = createGame('np1-4-1');
    if (start === null) throw new Error('Expected a valid board.');
    const mismatch = activateCard(activateCard(start, 0), 1);
    expect(decodeSnapshot(encodeSnapshot(start))?.started).toBe(false);
    expect(decodeSnapshot(encodeSnapshot(mismatch))).toEqual(mismatch);
  });

  it('rejects malformed, extra-key, out-of-range, and inconsistent state', () => {
    const selection = { kind: 'mismatch', first: 1, second: 2, remainingMs: 300 };
    const valid = {
      version: 1, boardCode: 'np1-4-1', matched: [0, 11], selection,
      moves: 2, elapsedMs: 1500, started: true,
    };
    const bad = [
      '{', JSON.stringify({ ...valid, extra: true }), JSON.stringify({ ...valid, version: 2 }),
      JSON.stringify({ ...valid, moves: 0 }), JSON.stringify({ ...valid, matched: [0] }),
      JSON.stringify({ ...valid, matched: [0, 0] }),
      JSON.stringify({ ...valid, matched: [0, 11, 1, 2] }),
      JSON.stringify({ ...valid, selection: { ...selection, remainingMs: 0 } }),
      JSON.stringify({ ...valid, selection: { kind: 'closed', index: 1 } }),
      JSON.stringify({ ...valid, boardCode: 'np1-4-1\n' }),
    ];
    for (const text of bad) expect(decodeSnapshot(text)).toBeNull();
  });

  it('enforces UTF-8 byte size rather than character count', () => {
    expect(decodeSnapshot(' '.repeat(65_537))).toBeNull();
  });
});
import { describe, expect, it } from 'vitest';
import { MAX_ELAPSED_MS } from './state.ts';
import { replayGame } from './replay.ts';

describe('replay format', () => {
  it('replays the documented simultaneous match', () => {
    const replay = '{"version":1,"boardCode":"np1-4-1","actions":[{"atMs":0,"index":0},{"atMs":0,"index":11}],"endMs":800}';
    const result = replayGame(replay);
    expect(result?.matched).toEqual([0, 11]);
    expect(result?.moves).toBe(1);
    expect(result?.elapsedMs).toBe(800);
  });

  it('closes an exact-time mismatch before an equal-time action', () => {
    const replay = JSON.stringify({
      version: 1, boardCode: 'np1-4-1',
      actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 1 }, { atMs: 800, index: 0 }], endMs: 800,
    });
    expect(replayGame(replay)?.selection).toEqual({ kind: 'one', index: 0 });
  });

  it('caps replayed elapsed time while accepting safe large timestamps', () => {
    const replay = JSON.stringify({ version: 1, boardCode: 'np1-4-1', actions: [{ atMs: 0, index: 0 }], endMs: Number.MAX_SAFE_INTEGER });
    expect(replayGame(replay)?.elapsedMs).toBe(MAX_ELAPSED_MS);
  });

  it('rejects malformed, unordered, oversized, or out-of-range actions', () => {
    const base = { version: 1, boardCode: 'np1-4-1', actions: [{ atMs: 0, index: 0 }], endMs: 0 };
    const bad = [
      '{', JSON.stringify({ ...base, extra: 1 }), JSON.stringify({ ...base, actions: [{ ...base.actions[0], extra: 1 }] }),
      JSON.stringify({ ...base, actions: [{ atMs: 1, index: 0 }, { atMs: 0, index: 1 }], endMs: 1 }),
      JSON.stringify({ ...base, actions: [{ atMs: 0, index: 16 }] }),
      JSON.stringify({ ...base, endMs: Number.MAX_SAFE_INTEGER + 1 }),
      JSON.stringify({ ...base, actions: Array.from({ length: 10_001 }, () => ({ atMs: 0, index: 0 })) }),
      ' '.repeat(1_048_577),
    ];
    for (const text of bad) expect(replayGame(text)).toBeNull();
  });
});

# Neon Pairs
Neon Pairs is a browser memory game that asks you to find every matching pair.

Read [Neon Pairs game specification and document map](docs/README.md) to build the game.

Follow the requirements in docs/ for this project.
