export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_BYTE_LIMIT = 65_536;

type SnapshotObject = {
  readonly version: 1;
  readonly boardCode: string;
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
};

export function encodeSnapshot(state: GameState): string {
  const value: SnapshotObject = {
    version: SNAPSHOT_VERSION,
    boardCode: state.board.boardCode,
    matched: state.matched,
    selection: state.selection,
    moves: state.moves,
    elapsedMs: state.elapsedMs,
    started: state.started,
  };
  return JSON.stringify(value);
}

export function decodeSnapshot(text: string): GameState | null {
  if (new TextEncoder().encode(text).length > SNAPSHOT_BYTE_LIMIT) return null;
  let value: unknown;
  try {
    value = JSON.parse(text);
  } catch {
    return null;
  }
  return readSnapshot(value);
}

function readSnapshot(value: unknown): GameState | null {
  if (!hasExactKeys(value, ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'])) {
    return null;
  }
  if (value.version !== SNAPSHOT_VERSION || typeof value.boardCode !== 'string') return null;
  if (!isUnknownArray(value.matched) || !isSafeCount(value.moves, MAX_MOVES)) return null;
  if (!isSafeCount(value.elapsedMs, MAX_ELAPSED_MS) || typeof value.started !== 'boolean') return null;

  const board = parseBoardCode(value.boardCode);
  if (board === null) return null;
  const matched = readMatched(value.matched, board.deck);
  if (matched === null) return null;
  const selection = readSelection(value.selection, board.deck, matched);
  if (selection === null) return null;

  const pairCount = matched.length / 2;
  const minimumMoves = pairCount + (selection.kind === SELECTION_KIND.mismatch ? 1 : 0);
  if (value.moves < minimumMoves) return null;
  const complete = matched.length === board.deck.length;
  if (complete && selection.kind !== SELECTION_KIND.closed) return null;
  if (!value.started) {
    if (value.moves !== 0 || value.elapsedMs !== 0 || matched.length !== 0 || selection.kind !== SELECTION_KIND.closed) {
      return null;
    }
  } else if (value.moves === 0 && selection.kind !== SELECTION_KIND.one) {
    return null;
  }

  const game = initialGame(board);
  return { ...game, matched: Object.freeze(matched), selection, moves: value.moves, elapsedMs: value.elapsedMs, started: value.started };
}

function readMatched(value: readonly unknown[], deck: readonly number[]): number[] | null {
  const matched: number[] = [];
  for (const index of value) {
    if (!isIndex(index, deck.length) || matched.includes(index)) return null;
    matched.push(index);
  }
  const matchedSet = new Set(matched);
  for (const index of matched) {
    const face = deck[index];
    if (face === undefined) return null;
    const partner = deck.findIndex((candidate, position) => candidate === face && position !== index);
    if (partner < 0 || !matchedSet.has(partner)) return null;
  }
  return matched;
}

function readSelection(value: unknown, deck: readonly number[], matched: readonly number[]): Selection | null {
  if (!isRecord(value) || typeof value.kind !== 'string') return null;
  if (value.kind === SELECTION_KIND.closed) {
    return hasExactKeys(value, ['kind']) ? { kind: SELECTION_KIND.closed } : null;
  }
  if (value.kind === SELECTION_KIND.one) {
    if (!hasExactKeys(value, ['kind', 'index']) || !isIndex(value.index, deck.length) || matched.includes(value.index)) return null;
    return { kind: SELECTION_KIND.one, index: value.index };
  }
  if (value.kind === SELECTION_KIND.mismatch) {
    if (!hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs'])) return null;
    if (!isIndex(value.first, deck.length) || !isIndex(value.second, deck.length)) return null;
    if (value.first === value.second || matched.includes(value.first) || matched.includes(value.second)) return null;
    if (deck[value.first] === deck[value.second] || !isSafeCount(value.remainingMs, MISMATCH_MS) || value.remainingMs === 0) {
      return null;
    }
    return { kind: SELECTION_KIND.mismatch, first: value.first, second: value.second, remainingMs: value.remainingMs };
  }
  return null;
}

function isIndex(value: unknown, length: number): value is number {
  return Number.isSafeInteger(value) && typeof value === 'number' && value >= 0 && value < length;
}

function isSafeCount(value: unknown, maximum: number): value is number {
  return Number.isSafeInteger(value) && typeof value === 'number' && value >= 0 && value <= maximum;
}

import { GRID_SIZES, isGridSize, type GridSize } from '../board.ts';
import { MAX_MOVES } from '../state.ts';

export interface StoragePort {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

const PREFERENCE_KEY = 'neon-pairs.preferences.v1';
const BEST_KEY = 'neon-pairs.best.v1';

export function readSavedSize(storage: StoragePort | null = browserStorage()): GridSize | null {
  try {
    if (storage === null) return null;
    const raw = storage.getItem(PREFERENCE_KEY);
    if (raw === null) return null;
    const value: unknown = JSON.parse(raw);
    return isRecord(value) && isGridSize(value.gridSize) ? value.gridSize : null;
  } catch {
    return null;
  }
}

export function saveSize(size: GridSize, storage: StoragePort | null = browserStorage()): void {
  try {
    storage?.setItem(PREFERENCE_KEY, JSON.stringify({ gridSize: size }));
  } catch {
    return;
  }
}

export function readBestScores(storage: StoragePort | null = browserStorage()): ReadonlyMap<GridSize, number> {
  const scores = new Map<GridSize, number>();
  try {
    if (storage === null) return scores;
    const raw = storage.getItem(BEST_KEY);
    if (raw === null) return scores;
    const value: unknown = JSON.parse(raw);
    if (!isRecord(value)) return scores;
    for (const size of GRID_SIZES) {
      const score = value[String(size)];
      if (Number.isSafeInteger(score) && typeof score === 'number' && score >= 0 && score <= MAX_MOVES) {
        scores.set(size, score);
      }
    }
  } catch {
    return new Map();
  }
  return scores;
}

export function saveBestScore(size: GridSize, moves: number, storage: StoragePort | null = browserStorage()): void {
  if (!Number.isSafeInteger(moves) || moves < 0 || moves > MAX_MOVES) return;
  try {
    if (storage === null) return;
    const scores = new Map(readBestScores(storage));
    const current = scores.get(size);
    if (current !== undefined && current <= moves) return;
    scores.set(size, moves);
    storage.setItem(BEST_KEY, JSON.stringify(Object.fromEntries(scores)));
  } catch {
    return;
  }
}

function browserStorage(): StoragePort | null {
  try {
    return typeof window === 'undefined' ? null : window.localStorage;
  } catch {
    return null;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export interface MillisecondChunk {
  readonly wholeMilliseconds: number;
  readonly remainder: number;
}

export function accumulateMilliseconds(delta: number, remainder: number): MillisecondChunk {
  const total = Math.max(0, delta) + Math.max(0, remainder);
  if (!Number.isFinite(total) || total >= Number.MAX_SAFE_INTEGER) {
    return { wholeMilliseconds: Number.MAX_SAFE_INTEGER, remainder: 0 };
  }
  const wholeMilliseconds = Math.floor(total);
  return { wholeMilliseconds, remainder: total - wholeMilliseconds };
}
import { useCallback, useEffect, useRef, type MutableRefObject } from 'react';
import { advanceGame, isWon, type GameState } from '../state.ts';
import { accumulateMilliseconds } from './whole-time.ts';

export interface SessionClock {
  flush(): GameState;
  reset(): void;
}

export function useSessionClock(
  gameRef: MutableRefObject<GameState>,
  pausedRef: MutableRefObject<boolean>,
  revision: number,
  commit: (game: GameState) => void,
): SessionClock {
  const activeRevision = useRef(revision);
  const lastNow = useRef(0);
  const remainder = useRef(0);
  const visible = useRef(false);
  activeRevision.current = revision;

  const flushRevision = useCallback((expectedRevision: number): GameState => {
    if (expectedRevision !== activeRevision.current) return gameRef.current;
    const now = performance.now();
    const delta = Math.max(0, now - lastNow.current);
    lastNow.current = now;
    const current = gameRef.current;
    if (!visible.current || pausedRef.current || !current.started || isWon(current)) return current;

    const chunk = accumulateMilliseconds(delta, remainder.current);
    remainder.current = chunk.remainder;
    if (chunk.wholeMilliseconds > 0) {
      const next = advanceGame(current, chunk.wholeMilliseconds);
      if (next !== current) commit(next);
    }
    return gameRef.current;
  }, [commit, gameRef, pausedRef]);

  const flush = useCallback(() => flushRevision(activeRevision.current), [flushRevision]);

  const reset = useCallback(() => {
    lastNow.current = performance.now();
    remainder.current = 0;
  }, []);

  useEffect(() => {
    const expectedRevision = revision;
    lastNow.current = performance.now();
    remainder.current = 0;
    visible.current = !document.hidden;
    const interval = window.setInterval(() => flushRevision(expectedRevision), 100);

    const onVisibilityChange = () => {
      if (expectedRevision !== activeRevision.current) return;
      flushRevision(expectedRevision);
      visible.current = !document.hidden;
      lastNow.current = performance.now();
    };
    document.addEventListener('visibilitychange', onVisibilityChange);
    return () => {
      window.clearInterval(interval);
      document.removeEventListener('visibilitychange', onVisibilityChange);
    };
  }, [flushRevision, revision]);

  return { flush, reset };
}
import { describe, expect, it } from 'vitest';
import { accumulateMilliseconds } from './whole-time.ts';

describe('active clock precision', () => {
  it('carries fractional time across render ticks and pauses', () => {
    const first = accumulateMilliseconds(0.4, 0);
    const second = accumulateMilliseconds(0.4, first.remainder);
    const third = accumulateMilliseconds(0.4, second.remainder);
    expect([first.wholeMilliseconds, second.wholeMilliseconds, third.wholeMilliseconds]).toEqual([0, 0, 1]);
    expect(third.remainder).toBeCloseTo(0.2);
  });

  it('ignores a backwards clock sample and bounds an unsafe delay', () => {
    expect(accumulateMilliseconds(-20, 0.5)).toEqual({ wholeMilliseconds: 0, remainder: 0.5 });
    expect(accumulateMilliseconds(Infinity, 0)).toEqual({ wholeMilliseconds: Number.MAX_SAFE_INTEGER, remainder: 0 });
  });
});

import { useCallback, useRef, useState } from 'react';
import { GRID_SIZES, isGridSize, parseBoardCode, type GridSize } from '../board.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import {
  activateCard as activateCardCore,
  createGame,
  formatElapsedTime,
  isWon,
  matchedPairCount,
  SELECTION_KIND,
