    if (pausedRef.current) return;
    const before = clock.flush();
    const next = activateCardCore(before, index);
    if (next === before) return;
    commit(next);
    if (before.selection.kind !== SELECTION_KIND.one || next.selection.kind === SELECTION_KIND.one) return;

    if (next.selection.kind === SELECTION_KIND.mismatch) {
