  const start = useCallback((code: string) => {
    clock.flush();
    const next = createGame(code);
    if (next === null) return;
    replace(next);
    saveSize(next.board.size);
  }, [clock, replace]);

  const newGame = useCallback(() => {
    const current = clock.flush();
    start(newBoardCode(current.board.size, current.board.seed));
  }, [clock, start]);

  const restart = useCallback(() => {
    const current = clock.flush();
    start(current.board.boardCode);
  }, [clock, start]);

  const changeSize = useCallback((size: GridSize) => {
    if (!isGridSize(size) || gameRef.current.board.size === size) return;
    clock.flush();
    start(newBoardCode(size));
  }, [clock, start]);

  const loadBoard = useCallback((draft: string) => {
    clock.flush();
    const board = parseBoardCode(draft.trim());
    if (board === null) {
      publish('Invalid board code.', true);
      return;
    }
    const next = createGame(board.boardCode);
    if (next === null) return;
    replace(next);
    saveSize(next.board.size);
    publish('Loaded board.', true);
  }, [clock, publish, replace]);

  const loadSnapshot = useCallback((text: string) => {
    clock.flush();
    const next = decodeSnapshot(text);
    if (next === null) {
      publish('Invalid snapshot.', true);
      return;
    }
    const complete = isWon(next);
    replace(next, !complete);
    saveSize(next.board.size);
    publish(complete ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.', true);
  }, [clock, publish, replace]);

  const resume = useCallback(() => {
    if (!pausedRef.current) return;
    pausedRef.current = false;
    setSnapshotPaused(false);
    clock.reset();
  }, [clock]);

  const exportSnapshot = useCallback(() => {
    const snapshot: unknown = JSON.parse(encodeSnapshot(clock.flush()));
    return JSON.stringify(snapshot, null, 2);
  }, [clock]);

  return {
    game,
    gridSizes: GRID_SIZES,
    bestMoves: bestScores.get(game.board.size) ?? null,
    dealRevision: revision,
    snapshotPaused,
    celebration,
    announcement,
    status,
    activateCard,
    newGame,
    restart,
    changeSize,
    loadBoard,
    loadSnapshot,
    resume,
    exportSnapshot,
  };
}

function recordBest(
  game: GameState,
  bestRef: React.MutableRefObject<ReadonlyMap<GridSize, number>>,
  setBestScores: (value: ReadonlyMap<GridSize, number>) => void,
): void {
  const size = game.board.size;
  const existing = bestRef.current.get(size);
  if (existing !== undefined && existing <= game.moves) return;
  const next = new Map(bestRef.current);
  next.set(size, game.moves);
  bestRef.current = next;
  setBestScores(next);
  saveBestScore(size, game.moves);
}
import type { GridSize } from '../board.ts';

const MAX_SEED = 2_147_483_646;

export function newBoardCode(size: GridSize, previousSeed?: number): string {
  const values = new Uint32Array(1);
  let value: number;
  try {
    value = window.crypto.getRandomValues(values)[0] ?? 0;
  } catch {
    value = Math.floor(Math.random() * MAX_SEED);
  }
  let seed = (value % MAX_SEED) + 1;
  if (seed === previousSeed) seed = seed === MAX_SEED ? 1 : seed + 1;
  return `np1-${size}-${seed}`;
}

